#include <stdlib.h>

struct T { int key; struct T *left, *right; };

struct T *new_node(int k) {
    struct T *t = malloc(sizeof *t);
    if (!t) abort();
    t->key = k;
    t->left = t->right = NULL;
    return t;
}

struct T *find(struct T *t, int k) {
    while (t && t->key != k)
        t = (k < t->key) ? t->left : t->right;
    return t;
}

struct T *insert(struct T *t, int k) {
    if (!t) return new_node(k);
    if (k < t->key)      t->left  = insert(t->left, k);
    else if (k > t->key) t->right = insert(t->right, k);
    return t;
}

struct T *min_node(struct T *t) {
    while (t->left) t = t->left;
    return t;
}

struct T *delete(struct T *t, int k) {
    if (!t) return NULL;
    if (k < t->key)      t->left  = delete(t->left, k);
    else if (k > t->key) t->right = delete(t->right, k);
    else {
        if (!t->left)  { struct T *r = t->right; free(t); return r; }
        if (!t->right) { struct T *l = t->left;  free(t); return l; }
        struct T *s = min_node(t->right);
        t->key = s->key;
        t->right = delete(t->right, s->key);
    }
    return t;
}

void inorder(const struct T *t, void (*visit)(int)) {
    if (!t) return;
    inorder(t->left, visit);
    visit(t->key);
    inorder(t->right, visit);
}

void free_tree(struct T *t) {      /* post-order */
    if (!t) return;
    free_tree(t->left);
    free_tree(t->right);
    free(t);
}

struct T *insert_iter(struct T *root, int k) {
    struct T *n = new_node(k), *p = NULL, *c = root;
    while (c) {
        p = c;
        if (k == c->key) { free(n); return root; }
        c = (k < c->key) ? c->left : c->right;
    }
    if (!p) return n;
    if (k < p->key) p->left = n; else p->right = n;
    return root;
}

/* largest key <= x, or -1 if none (keys assumed non-negative) */
int floor_key(const struct T *t, int x) {
    int best = -1;
    while (t) {
        if (t->key == x) return x;
        if (t->key < x) { best = t->key; t = t->right; }
        else t = t->left;
    }
    return best;
}

#include <stdbool.h>
#include <limits.h>

static bool ok(const struct T *t, long lo, long hi) {
    if (!t) return true;
    if (t->key <= lo || t->key >= hi) return false;
    return ok(t->left, lo, t->key) && ok(t->right, t->key, hi);
}

bool is_bst(const struct T *t) { return ok(t, LONG_MIN, LONG_MAX); }

const struct T *lca(const struct T *t, int a, int b) {
    while (t) {
        if (a < t->key && b < t->key)      t = t->left;
        else if (a > t->key && b > t->key) t = t->right;
        else return t;
    }
    return NULL;
}

struct T *build(const int *a, int lo, int hi) {   /* [lo, hi) */
    if (lo >= hi) return NULL;
    int mid = lo + (hi - lo) / 2;
    struct T *t = new_node(a[mid]);
    t->left  = build(a, lo, mid);
    t->right = build(a, mid + 1, hi);
    return t;
}
